from pathlib import Path
import re

ROOT = Path('manuscript/ga1')


def replace_once(filename: str, old: str, new: str):
    p = ROOT / filename
    text = p.read_text(encoding='utf-8')
    n = text.count(old)
    if n != 1:
        raise SystemExit(f'{filename}: expected replacement block once, got {n}: {old[:80]!r}')
    p.write_text(text.replace(old, new, 1), encoding='utf-8')

