# Report UI density and true C4-style prose length (strip title/header according to validator convention is done later too).
for fn in [f58, f59, f61]:
    p = ROOT / fn
    text = p.read_text(encoding='utf-8')
    pos = text.find('# 제')
    body = text[pos:] if pos >= 0 else text
    paras = [x.strip() for x in re.split(r'\n\s*\n', body) if x.strip()]
    ui = [q for q in paras if q.startswith('[') and q.endswith(']')]
    ui_chars = sum(len(q) for q in ui)
    print(f'{fn}: body_chars={len(body)} ui_paras={len(ui)} ui_ratio={ui_chars/max(len(body),1):.4f} max_ui_run=', end='')
    cur=maxrun=0
    for q in paras:
        if q.startswith('[') and q.endswith(']'):
            cur += 1; maxrun=max(maxrun,cur)
        else:
            cur=0
    print(maxrun)
